import brainmass, brainstate, braintools, brainunit as u
import jax.numpy as jnp
DT=.1*u.ms; N=3; M=201; C=jnp.array([[0.,1.,0.],[1.,0.,1.],[0.,1.,0.]])
class Net(brainstate.nn.Module):
 def __init__(s): super().__init__(); s.node=brainmass.FitzHughNagumoStep(in_size=N,init_V=braintools.init.Constant(0.),init_w=braintools.init.Constant(0.)); s.h=None;s.p=None
 def init_state(s,batch_size=None): s.h=brainstate.HiddenState(jnp.zeros((M,N)));s.p=brainstate.ShortTermState(jnp.array(0,dtype=jnp.int32))
 def update(s,stim,k,d):
  old=s.h.value[(s.p.value-d)%M]; c=brainmass.diffusive_coupling(jnp.broadcast_to(old,C.shape),s.node.V.value,C,k);s.node.update(c+stim);s.h.value=s.h.value.at[s.p.value].set(s.node.V.value);s.p.value=(s.p.value+1)%M;return s.node.V.value

def run(k,dms,a):
 n=Net(); d=jnp.rint(dms/.1).astype(jnp.int32); ix=jnp.arange(2000)
 with brainstate.environ.context(dt=DT):
  brainstate.nn.init_all_states(n)
  def step(i):
   t=i*DT; stim=jnp.where((t>=20*u.ms)&(t<40*u.ms),jnp.array([a,0.,0.]),jnp.zeros(3));return n.update(stim,k,d)
  return brainstate.transform.for_loop(step,ix)
ks=jnp.array([.2,.4,.6,.8,1.,1.5,2.,3.,4.,6.,8.]); ds=jnp.ones_like(ks)*2; amps=jnp.ones_like(ks)*.5
O=brainstate.transform.vmap(run)(ks,ds,amps)
for k,v in zip(ks,O):
 a=v>.5; on=jnp.where(jnp.any(a,0),jnp.argmax(a,0)*.1,jnp.inf);print(float(k),jnp.max(v,0),on)
PY"

